<script setup>import {useForm} from '@inertiajs/vue3'; import {computed,ref} from 'vue'; import AppLayout from '../../Layouts/AppLayout.vue'; const props=defineProps({route:Object,sellers:Array,clients:Array,selectedIds:Array,lockedIds:Array,editing:Boolean,endpoints:Object}); const query=ref(''); const form=useForm({name:props.route.name||'',scheduled_date:String(props.route.scheduled_date||new Date().toISOString().slice(0,10)).slice(0,10),scheduled_until:'',starts_at:String(props.route.starts_at||'08:00').slice(0,5),collector_id:props.route.collector_id||'',notes:props.route.notes||'',client_ids:[...props.selectedIds]}); const filtered=computed(()=>props.clients.filter(c=>`${c.full_name} ${c.neighborhood} ${c.address}`.toLowerCase().includes(query.value.toLowerCase()))); const locked=id=>props.lockedIds.includes(id); const toggle=(id,on)=>{if(locked(id))return;if(on&&!form.client_ids.includes(id))form.client_ids.push(id);if(!on)form.client_ids=form.client_ids.filter(x=>x!==id)}; const submit=()=>form.transform(d=>props.editing?{...d,_method:'put'}:d).post(props.endpoints.save);</script>
<template><AppLayout :title="editing?'Editar ruta':'Nueva ruta'" eyebrow="Operación en campo" description="Planifica al cobrador y el orden de clientes sin alterar su asignación de cartera."><template #header-actions><a :href="endpoints.index" class="btn-secondary">Volver</a></template><form class="grid gap-4 xl:grid-cols-[360px_1fr]" @submit.prevent="submit"><section class="card h-fit p-5"><h2 class="font-semibold">Planificación</h2><div class="mt-4 space-y-4"><label class="field-label">Nombre *<input v-model="form.name" class="control" required></label><label class="field-label">Fecha inicial *<input v-model="form.scheduled_date" type="date" class="control"></label><label v-if="!editing" class="field-label">Fecha final<input v-model="form.scheduled_until" type="date" :min="form.scheduled_date" class="control"></label><label class="field-label">Hora de salida<input v-model="form.starts_at" type="time" class="control"></label><label class="field-label">Cobrador *<select v-model="form.collector_id" class="control"><option value="">Seleccionar</option><option v-for="seller in sellers" :key="seller.id" :value="seller.id">{{seller.display_name}} · {{seller.code}}</option></select></label><label class="field-label">Notas<textarea v-model="form.notes" class="control"></textarea></label></div></section><section class="card overflow-hidden"><div class="section-heading"><div class="flex justify-between"><div><h2 class="font-semibold">Clientes de la ruta</h2><p class="text-[11px] text-slate-400">Los clientes con gestiones registradas permanecen bloqueados.</p></div><span class="badge bg-blue-50 text-blue-700">{{form.client_ids.length}} seleccionados</span></div><input v-model="query" class="control" placeholder="Buscar nombre, barrio o dirección"></div><div class="max-h-[600px] divide-y overflow-y-auto"><label v-for="client in filtered" :key="client.id" class="flex items-center gap-3 p-4" :class="locked(client.id)?'bg-slate-50':'hover:bg-blue-50/40'"><input type="checkbox" :checked="form.client_ids.includes(client.id)" :disabled="locked(client.id)" @change="toggle(client.id,$event.target.checked)"><div class="min-w-0 flex-1"><p class="font-semibold">{{client.full_name}}</p><p class="truncate text-[10px] text-slate-400">{{client.neighborhood}} · {{client.address}}</p></div><span v-if="locked(client.id)" class="text-[10px] text-amber-700">Con historial</span></label></div><div class="p-4"><p v-if="form.errors.client_ids" class="mb-2 text-xs text-rose-600">{{form.errors.client_ids}}</p><button class="btn-primary">{{editing?'Guardar cambios':'Crear ruta'}}</button></div></section></form></AppLayout></template>
